"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";

interface TabsContextValue {
  value: string;
  setValue: (value: string) => void;
  idBase: string;
}

const TabsContext = React.createContext<TabsContextValue | null>(null);

function useTabsContext(component: string): TabsContextValue {
  const ctx = React.useContext(TabsContext);
  if (!ctx) throw new Error(`<${component}> must be used inside <Tabs>`);
  return ctx;
}

const styles = stylex.create({
  list: {
    display: "flex",
    alignItems: {
      default: "baseline",
      [mq.phone]: "stretch",
    },
    gap: {
      default: 22,
      [mq.phone]: 0,
    },
    width: {
      default: null,
      [mq.phone]: "100%",
    },
    maxWidth: {
      default: 360,
      [mq.phone]: "none",
    },
    borderWidth: 0,
    borderStyle: "none",
    borderBottomWidth: {
      default: 0,
      [mq.phone]: raster.hairline,
    },
    borderBottomStyle: {
      default: "none",
      [mq.phone]: "solid",
    },
    borderBottomColor: {
      default: "transparent",
      [mq.phone]: raster.divider,
    },
    boxShadow: "none",
    backgroundColor: "transparent",
  },
  tab: {
    appearance: "none",
    boxSizing: "border-box",
    flexGrow: {
      default: null,
      [mq.phone]: 1,
    },
    flexShrink: {
      default: null,
      [mq.phone]: 1,
    },
    flexBasis: {
      default: null,
      [mq.phone]: 0,
    },
    display: {
      default: null,
      [mq.phone]: "inline-flex",
    },
    alignItems: {
      default: null,
      [mq.phone]: "center",
    },
    justifyContent: {
      default: null,
      [mq.phone]: "center",
    },
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
    paddingBlock: {
      default: 8,
      [mq.phone]: 0,
    },
    paddingInline: {
      default: 0,
      [mq.phone]: 8,
    },
    fontSize: {
      default: 14,
      [mq.phone]: raster.controlFs,
    },
    fontFamily: "inherit",
    fontWeight: 400,
    color: raster.gray,
    letterSpacing: "-0.01em",
    textDecoration: "none",
    textAlign: {
      default: "left",
      [mq.phone]: "center",
    },
    backgroundColor: "transparent",
    backgroundImage: "none",
    boxShadow: "none",
    borderWidth: 0,
    borderStyle: "none",
    borderRadius: 0,
    cursor: "pointer",
  },
  active: {
    color: raster.ink,
    fontWeight: 600,
    borderWidth: 0,
    borderStyle: "none",
    boxShadow: "inset 0 -1px 0",
  },
});

export interface TabsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export function Tabs({ value, defaultValue, onValueChange, children, ...props }: TabsProps) {
  const idBase = React.useId();
  const [inner, setInner] = React.useState(defaultValue ?? "");
  const isControlled = value !== undefined;
  const current = isControlled ? value : inner;
  const setValue = (next: string) => {
    if (!isControlled) setInner(next);
    onValueChange?.(next);
  };
  return (
    <div {...props}>
      <TabsContext.Provider value={{ value: current, setValue, idBase }}>
        {children}
      </TabsContext.Provider>
    </div>
  );
}

export function TabList({ className, style, onKeyDown, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(e);
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    const tabs = Array.from(
      e.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]:not(:disabled)'),
    );
    const index = tabs.indexOf(document.activeElement as HTMLButtonElement);
    if (index === -1) return;
    e.preventDefault();
    const next = e.key === "ArrowRight" ? (index + 1) % tabs.length : (index - 1 + tabs.length) % tabs.length;
    tabs[next]?.focus();
    tabs[next]?.click();
  };
  const sx = rs(["rs-tabs", className], styles.list);
  return (
    <div
      role="tablist"
      onKeyDown={handleKeyDown}
      {...props}
      className={sx.className}
      style={{ ...sx.style, ...style }}
    />
  );
}

export interface TabProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
}

export function Tab({ value, className, style, onClick, ...props }: TabProps) {
  const ctx = useTabsContext("Tab");
  const selected = ctx.value === value;
  const sx = rs(["rs-tab", selected && "rs-tab-active", className], styles.tab, selected && styles.active);
  return (
    <button
      type="button"
      role="tab"
      id={`${ctx.idBase}-tab-${value}`}
      aria-selected={selected}
      aria-controls={`${ctx.idBase}-panel-${value}`}
      tabIndex={selected ? 0 : -1}
      onClick={(e) => {
        ctx.setValue(value);
        onClick?.(e);
      }}
      {...props}
      className={sx.className}
      style={{ ...sx.style, ...style }}
    />
  );
}

export interface TabPanelProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
}

export function TabPanel({ value, ...props }: TabPanelProps) {
  const ctx = useTabsContext("TabPanel");
  const selected = ctx.value === value;
  return (
    <div
      role="tabpanel"
      id={`${ctx.idBase}-panel-${value}`}
      aria-labelledby={`${ctx.idBase}-tab-${value}`}
      hidden={!selected}
      {...props}
    />
  );
}

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import type { CompiledStyles, InlineStyles } from "@stylexjs/stylex";
import { cx } from "./cx";

type Nested<T> = T | ReadonlyArray<Nested<T>>;

/** Exactly what stylex.props accepts: compiled leaves, falsy, nested arrays, or a leaf with inline styles. */
export type Leaves = ReadonlyArray<Nested<null | undefined | CompiledStyles | boolean | Readonly<[CompiledStyles, InlineStyles]>>>;

type StyleXProps = { className?: string; style?: CSSProperties };

/**
 * The one seam every component styles through: semantic rs-* class names
 * (the CSS-first contract, and what packages/core generates CSS for) merged
 * with the compiled StyleX leaves that paint the React tree.
 */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: Leaves): StyleXProps {
  const sx = stylex.props(...styles) as StyleXProps;
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}
